import { KEYS, getJson } from "./store.mjs";

// Access-control policies. The one policy the server acts on is
// PublicCanRead: it lets an unsigned GET/HEAD read the covered scope. A
// policy can only broaden access, never deny a capability holder, and the
// most specific scope wins: the resource's own policy, else its
// collection's, else the space's.

export const PUBLIC_CAN_READ = "PublicCanRead";

export function policyKey({ collectionId, resourceId }) {
  if (resourceId !== undefined) {
    return KEYS.resourcePolicy(collectionId, resourceId);
  }
  if (collectionId !== undefined) {
    return KEYS.collectionPolicy(collectionId);
  }
  return KEYS.spacePolicy();
}

// Whether a PublicCanRead policy covers the scope named by the ids.
export async function isPubliclyReadable(bucket, { collectionId, resourceId }) {
  const keys = [];
  if (collectionId !== undefined && resourceId !== undefined) {
    keys.push(KEYS.resourcePolicy(collectionId, resourceId));
  }
  if (collectionId !== undefined) {
    keys.push(KEYS.collectionPolicy(collectionId));
  }
  keys.push(KEYS.spacePolicy());
  for (const key of keys) {
    const stored = await getJson(bucket, key);
    if (stored?.doc?.type === PUBLIC_CAN_READ) {
      return true;
    }
  }
  return false;
}
